def transform(grid):
    h, w = len(grid), len(grid[0])

    # Full uniform rows and columns are the separators.
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    sep_color = grid[sep_rows[0]][0]
    sep_cols = [c for c in range(w) if all(grid[r][c] == sep_color for r in range(h))]

    def ranges(n, separators):
        result = []
        start = 0
        for p in separators:
            if start < p:
                result.append((start, p))
            start = p + 1
        if start < n:
            result.append((start, n))
        return result

    row_ranges = ranges(h, sep_rows)
    col_ranges = ranges(w, sep_cols)

    counts = {}
    for row in grid:
        for value in row:
            if value != sep_color:
                counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    marker = min(counts, key=counts.get)

    return [
        [
            1 if sum(grid[r][c] == marker
                     for r in range(r0, r1)
                     for c in range(c0, c1)) == 2 else background
            for c0, c1 in col_ranges
        ]
        for r0, r1 in row_ranges
    ]
